/**
 * // This is the Master's API interface.
 * // You should not implement it, or speculate about its implementation
 */
class Master {
public:
    int guess(string word);
};

class Solution {
public:
    int match(const string& a, const string& b) {
        int m = 0;
        for (int i = 0; i < 6; i++) if (a[i] == b[i]) m++;
        return m;
    }

    void findSecretWord(vector<string>& words, Master& master) {
        int n = words.size();
        vector<int> candidates;
        for (int i = 0; i < n; i++) candidates.push_back(i);

        while (!candidates.empty()) {
            if (candidates.size() == 1) {
                master.guess(words[candidates[0]]);
                return;
            }
            if (candidates.size() == 2) {
                int k = master.guess(words[candidates[0]]);
                if (k == 6) return;
                master.guess(words[candidates[1]]);
                return;
            }

            int bestIdx = candidates[0];
            int bestMax = n + 1;
            for (int idx : candidates) {
                int cnt[7] = {};
                for (int other : candidates) {
                    if (other == idx) continue;
                    cnt[match(words[idx], words[other])]++;
                }
                int mx = 0;
                for (int i = 0; i < 7; i++) if (cnt[i] > mx) mx = cnt[i];
                if (mx < bestMax) {
                    bestMax = mx;
                    bestIdx = idx;
                }
            }

            int k = master.guess(words[bestIdx]);
            if (k == 6) return;

            vector<int> next;
            for (int c : candidates) {
                if (c == bestIdx) continue;
                if (match(words[bestIdx], words[c]) == k) next.push_back(c);
            }
            candidates = next;
        }
    }
};
